  'Valores em kwanzas (Kz). Os totais acompanham os filtros.': 'ዋጋታት ብክዋንዛ (Kz)። ጠቕላላታት ንመጻረዪታት ይስዕቡ።',
  'A exportação de vendas do Pinguim BO que temos indica só se cada documento está liquidado. Para separar o que foi recebido em dinheiro e em Multicaixa, a exportação tem de trazer o meio de cobrança de cada documento (ou o mapa de recebimentos do Pinguim BO).':
    'ካብ Pinguim BO ዘሎና ናይ መሸጣታት ሓበሬታ ነፍሲ ወከፍ ሰነድ ተኸፊሉ እንተሎ ጥራይ የርኢ። ብጥረ ገንዘብን ብMulticaixaን ዝተኣከበ ገንዘብ ንምፍላይ፡ እቲ ዝወጽእ ሓበሬታ ናይ ነፍሲ ወከፍ ሰነድ ኣገባብ ክፍሊት ክሕዝ ኣለዎ (ወይ ናይ Pinguim BO ጸብጻብ ዝተኣከበ ገንዘብ)።',
  Activos: 'ንጡፋት',
