    'ኣካውንታት ገና ካብቲ ኣረጊት ዝርዝር (geo/auth/config_users.php) ይመጹ ኣለዉ። ፕሮፋይላት፡ መስመራትን ግዴታዊ ኢመይልን ንምትግባር ሓድሽ ዝርዝር ብ ferramentas/utilizadores.php ፍጠሩ።',
