  'O Excel não chegou ao servidor. Tente de novo.': 'እቲ Excel ናብ ሰርቨር ኣይበጽሐን። እንደገና ፈትኑ።',
  'O ficheiro não tem documentos.': 'እቲ ፋይል ሰነዳት የብሉን።',
  'O ficheiro para o SAP precisa do servidor da plataforma (PHP).': 'ፋይል ን SAP ሰርቨር ናይቲ መድረኽ የድልዮ።',
  'O seu perfil não permite gerar o ficheiro para o SAP.': 'ፕሮፋይልኩም ፋይል ን SAP ንምድላው ኣየፍቅድን።',
  'Os erros impedem a geração do ficheiro; os avisos não.': 'ጌጋታት ምድላው ፋይል ይዓግቱ፤ መጠንቀቕታታት ግን ኣይዓግቱን።',
  'Para cada rota: loja, depósito e empregado de vendas como existem no SAP. Em branco fica o padrão mostrado.':
    'ንነፍሲ ወከፍ መስመር፦ ድኳን፡ ቦታ SAP ከምኡ’ውን ሰራሕተኛ መሸጣ ከምቲ ኣብ SAP ዘሎ። ባዶ እንተኾይኑ እቲ ዝርአ ንቡር ዋጋ ይጸንሕ።',
  'Período escolhido em cima: {a} a {b}.': 'ኣብ ላዕሊ ዝተመርጸ እዋን፦ ካብ {a} ክሳብ {b}።',
  Por: 'ብ',
  'Prefixo da loja e do empregado': 'መቕድም ድኳንን ሰራሕተኛን',
  'Pré-visualização do ficheiro': 'ቅድመ ትርኢት ፋይል',
  'Só documentos ainda não enviados': 'ገና ዘይተሰደዱ ሰነዳት ጥራይ',
  'Total facturado': 'ጠቕላላ ዝተፋኽተረ',
  'Uma linha por artigo, como no modelo de carregamento de vendas do SAP. O total, o numerário e o Multicaixa são do documento e repetem-se em cada linha.':
    'ንነፍሲ ወከፍ ኣቕሓ ሓደ ረድፊ፡ ከምቲ ሞዴል ምጽዓን መሸጣ ናይ SAP። ጠቕላላ፡ ጥረ ገንዘብን Multicaixaን ናይቲ ሰነድ እዮም፡ ኣብ ነፍሲ ወከፍ ረድፊ ድማ ይድገሙ።',
  'Unidade por omissão': 'ንቡር ኣሃዱ',
  Verificação: 'ምርግጋጽ',
  'excluídos deste ficheiro': 'ካብዚ ፋይል ዝተገለሉ',
  'incluídos outra vez': 'እንደገና ዝኣተዉ',
  obrigatório: 'ግዴታዊ',
  '{d}: a soma das linhas ({a}) não bate com o total do documento ({b}).': '{d}፦ ድምር ረድፍታት ({a}) ምስ ጠቕላላ ሰነድ ({b}) ኣይሰማማዕን።',
  '{d}: linha «{a}» sem código de artigo.': '{d}፦ ረድፊ «{a}» ኮድ ኣቕሓ የብሉን።',
  '{d}: o documento não tem linhas de artigo.': '{d}፦ እቲ ሰነድ ረድፍታት ኣቕሓ የብሉን።',
  '{d}: {v} pagos por {m}; o modelo só tem numerário e Multicaixa.': '{d}፦ {v} ብ{m} ተኸፊሉ፤ እቲ ሞዴል ጥረ ገንዘብን Multicaixaን ጥራይ ኣለዎ።',
  '{n} avisos': '{n} መጠንቀቕታታት',
  '{n} avisos (ver a lista na página). Pode gerar na mesma.': '{n} መጠንቀቕታታት (ኣብቲ ገጽ ዘሎ ዝርዝር ርኣዩ)። ብኡ መንገዲ ከተዳልዉ ትኽእሉ ኢኹም።',
  '{n} documentos, {l} linhas, {v} facturados, de {a} a {b}. Os documentos ficam marcados como incluídos neste ficheiro.':
    '{n} ሰነዳት፡ {l} ረድፍታት፡ {v} ዝተፋኽተረ፡ ካብ {a} ክሳብ {b}። እቶም ሰነዳት ኣብዚ ፋይል ከም ዝኣተዉ ይምልከቱ።',
  '{n} linhas de artigo': '{n} ረድፍታት ኣቕሓ',
  '… e mais {n}.': '… ካልኦት {n}።',
  'A guardar…': 'ይቕመጥ ኣሎ…',
  'A lista de destinatários está vazia (Listas → Destinatários).': 'ዝርዝር ተቐበልቲ ባዶ እዩ (ዝርዝራት → ተቐበልቲ)።',
  'A publicar…': 'ይዝርጋሕ ኣሎ…',
