  'Alterações por guardar': 'ዘይተቐመጡ ለውጥታት',
  'Alterações por publicar': 'ዘይተዘርግሑ ለውጥታት',
  'Armazém de carga': 'መኽዘን ጽዕነት',
  'Armazéns de carga (um por linha)': 'መኻዝን ጽዕነት (ኣብ ነፍሲ ወከፍ መስመር ሓደ)',
  'Armazéns e viaturas': 'መኻዝንን ተሽከርካሪታትን',
  'Artigos carregados nas carrinhas, pela ordem do Excel.': 'ኣብ ቫናት ዝተጻዕኑ ኣቕሑ፡ ብመሰረት ስርዓት Excel።',
  'Copiado o plano de {d}. Corrija o que mudou hoje.': 'መደብ ናይ {d} ተቐዲሑ። ሎሚ ዝተቐየረ ኣርምዩ።',
