  Destinatários: 'ተቐበልቲ',
  'Dia do plano': 'መዓልቲ መደብ',
  'Dia seguinte': 'ዝቕጽል መዓልቲ',
  'Dias anteriores': 'ዝሓለፉ መዓልታት',
  'Mensagem de teste enviada para {e}.': 'ናይ ፈተነ ኢመይል ናብ {e} ተሰዲዱ።',
  'Mensagem reenviada.': 'ኢመይል እንደገና ተሰዲዱ።',
