  'Nenhuma rota sai neste dia.': 'ኣብዛ መዓልቲ ዝወጽእ መስመር የለን።',
  'Nota da rectificação': 'መዘኻኸሪ እርማት',
  'Nota para os destinatários': 'መዘኻኸሪ ንተቐበልቲ',
  'Não encontrei o cabeçalho do plano (SALES PERSON) no ficheiro.': 'ኣብቲ ፋይል ኣርእስቲ መደብ (SALES PERSON) ኣይተረኽበን።',
  'Não foi possível ler o Excel.': 'Excel ምንባብ ኣይተኻእለን።',
  'Não foi possível publicar.': 'ምዝርጋሕ ኣይተኻእለን።',
  'Não foi possível enviar.': 'ምስዳድ ኣይተኻእለን።',
  'Não sai': 'ኣይወጽእን',
  'O Excel do plano não chegou ao servidor. Tente de novo.': 'Excel መደብ ናብ ሰርቨር ኣይበጽሐን። እንደገና ፈትኑ።',
  'A mensagem da versão {v} não seguiu: {e}': 'ኢመይል ሕታም {v} ኣይተሰደደን፦ {e}',
  'O envio por correio electrónico ainda não está configurado no servidor. Pode preencher e publicar; a mensagem segue quando a configuração estiver feita (botão Reenviar).':
    'ምስዳድ ኢመይል ኣብ ሰርቨር ገና ኣይተዳለወን። ክትመልኡን ክተዘርግሑን ትኽእሉ ኢኹም፤ ምድላው ምስ ተወድአ ኢመይል ይስደድ (መልጎም «እንደገና ስደድ»)።',
  'O envio por correio electrónico ainda não está configurado no servidor: o plano fica publicado e o Excel disponível, e pode reenviar depois.':
    'ምስዳድ ኢመይል ኣብ ሰርቨር ገና ኣይተዳለወን፦ እቲ መደብ ይዝርጋሕ፣ Excel ይርከብ፣ ደሓር ድማ እንደገና ክትሰዱ ትኽእሉ ኢኹም።',
  'O ficheiro não tem rotas.': 'እቲ ፋይል መስመራት የብሉን።',
  'O plano de cargas precisa do servidor da plataforma (PHP).': 'መደብ ጽዕነት ሰርቨር መድረኽ የድልዮ።',
  'O plano deste dia ainda não foi publicado pela Logística.': 'መደብ ናይዛ መዓልቲ ገና ብሎጂስቲክስ ኣይተዘርግሐን።',
  'O que já preencheu para este dia é substituído pelo plano de {d}.': 'ንዛ መዓልቲ ዝመላእኩምዎ ብመደብ {d} ይትካእ።',
  'O que mudou (aparece na mensagem)': 'እንታይ ተቐይሩ (ኣብ ኢመይል ይርአ)',
  'O seu perfil não permite alterar o plano de cargas.': 'ፕሮፋይልኩም መደብ ጽዕነት ምቕያር ኣየፍቅደልኩምን።',
  Observações: 'ርእይቶታት',
