  'Plano publicado e enviado a {n} destinatários.': 'መደብ ተዘርጊሑ ናብ {n} ተቐበልቲ ተሰዲዱ።',
  'Plano publicado, mas a mensagem não seguiu: {e}': 'መደብ ተዘርጊሑ፣ ግን ኢመይል ኣይተሰደደን፦ {e}',
  'Planos guardados e publicados. Clique no dia para o abrir.': 'ዝተቐመጡን ዝተዘርግሑን መደባት። ንምኽፋት ኣብ መዓልቲ ጠውቑ።',
