  'Contas e perfis. Em Gerir altera o perfil, as rotas, o correio electrónico e a palavra-passe de cada conta.':
    'ኣካውንታትን ፕሮፋይላትን። ኣብ «ኣመሓድር» ፕሮፋይል፣ መስመራት፣ ኢመይልን መሕለፊ ቃልን ናይ ነፍሲ ወከፍ ኣካውንት ትቕይሩ።',
  'Contas e perfis. Só o super administrador cria e altera contas.': 'ኣካውንታትን ፕሮፋይላትን። ኣካውንታት ዝፈጥርን ዝቕይርን ሱፐር ኣመሓዳሪ ጥራይ እዩ።',
