  'Diferente da matriz original ({v})': 'ካብ ናይ መጀመርታ ሰንጠረዥ ፍቓዳት ዝተፈለየ ({v})',
  'Dois passos activados': 'ምርግጋጽ ብኽልተ ስጉምቲ ነቒሑ',
  'Dois passos retirados': 'ምርግጋጽ ብኽልተ ስጉምቲ ተኣልዩ',
  'Correio electrónico (obrigatório)': 'ኢመይል (ግዴታ)',
  'Correio electrónico alterado': 'ኢመይል ተቐይሩ',
  'Escolha o nível de cada perfil em cada página ou função e guarde. Contorno laranja: por guardar; azul: diferente da matriz original. A coluna SADM e as funções de administração não se alteram.':
    'ደረጃ ነፍሲ ወከፍ ፕሮፋይል ኣብ ነፍሲ ወከፍ ገጽ ወይ ተግባር ምረጹን ኣቐምጡን። ብርትኳናዊ ዶብ፦ ዘይተቐመጠ፤ ሰማያዊ፦ ካብ ናይ መጀመርታ ሰንጠረዥ ፍቓዳት ዝተፈለየ። ዓምዲ SADM ን ተግባራት ምምሕዳርን ኣይቕየሩን።',
  'Este perfil exige verificação em dois passos.': 'እዚ ፕሮፋይል ምርግጋጽ ብኽልተ ስጉምቲ ይሓትት።',
  'Este perfil exige verificação em dois passos. Active-a em Gerir, junto da pessoa, com o telemóvel dela.':
    'እዚ ፕሮፋይል ምርግጋጽ ብኽልተ ስጉምቲ ይሓትት። ኣብ «ኣመሓድር»፣ ምስቲ ሰብን ሞባይሉን ኮይንኩም ኣንቅሑዎ።',
  'Faça isto junto da pessoa: ela lê o código QR com o telemóvel.': 'ነዚ ምስቲ ሰብ ኮይንኩም ግበሩዎ፦ ንሱ ኮድ QR ብሞባይሉ የንብብ።',
  Fechar: 'ዕጸው',
