  'Guardar 1 alteração': '1 ለውጢ ኣቐምጥ',
  'Matriz guardada: 1 alteração.': 'ሰንጠረዥ ፍቓዳት ተቐሚጡ፦ 1 ለውጢ።',
  'Matriz guardada: {n} alterações.': 'ሰንጠረዥ ፍቓዳት ተቐሚጡ፦ {n} ለውጥታት።',
  'Aplica-se já nos dados; cada pessoa vê o menu novo quando actualizar a página.': 'ኣብ ሓበሬታ ብኡንብኡ ይትግበር፤ ነፍሲ ወከፍ ሰብ ገጽ ምስ ኣሐደሰ ሓድሽ ሜኑ ይርኢ።',
