  'Insira a sua palavra-passe. Fica confirmado durante 10 minutos.': 'መሕለፊ ቃልኩም ኣእትዉ። ምርግጋጽ ን 10 ደቓይቕ ይጸንሕ።',
  'Insira o código de 6 dígitos da aplicação de autenticação. Fica confirmado durante 10 minutos.': 'ካብ መተግበሪ ምርግጋጽ ዝመጽእ ኮድ 6 ኣሃዛት ኣእትዉ። ምርግጋጽ ን 10 ደቓይቕ ይጸንሕ።',
  'Já existe uma conta com este utilizador.': 'በዚ ስም ተጠቃሚ ዝተኸፍተ ኣካውንት ድሮ ኣሎ።',
  'Matriz alterada': 'ሰንጠረዥ ፍቓዳት ተቐይሩ',
  'Matriz guardada: {n} alterações. Aplica-se já nos dados; cada pessoa vê o menu novo quando actualizar a página.':
    'ሰንጠረዥ ፍቓዳት ተቐሚጡ፦ {n} ለውጥታት። ኣብ ሓበሬታ ብኡንብኡ ይትግበር፤ ነፍሲ ወከፍ ሰብ ገጽ ምስ ኣሐደሰ ሓድሽ ሜኑ ይርኢ።',
  'Matriz original reposta': 'ናይ መጀመርታ ሰንጠረዥ ፍቓዳት ተመሊሱ',
  'Matriz original reposta.': 'ናይ መጀመርታ ሰንጠረዥ ፍቓዳት ተመሊሱ።',
