  'Não pode retirar a verificação em dois passos da sua própria conta.': 'ካብ ናይ ባዕልኹም ኣካውንት ምርግጋጽ ብኽልተ ስጉምቲ ከተልግሱ ኣይትኽእሉን ኢኹም።',
  'Não pode retirar o seu próprio perfil de super administrador nem desactivar a sua conta.':
    'ናይ ባዕልኹም ፕሮፋይል ሱፐር ኣመሓዳሪ ከተልግሱ ወይ ኣካውንትኩም ዘይንጡፍ ክትገብሩ ኣይትኽእሉን ኢኹም።',
  'O correio electrónico é obrigatório e tem de ser válido.': 'ኢመይል ግዴታ እዩ፣ ብቑዕ ድማ ክኸውን ኣለዎ።',
  'O utilizador tem de ter 3 a 40 caracteres: letras, números, ponto, hífen ou sublinhado.':
    'ስም ተጠቃሚ ካብ 3 ክሳብ 40 ምልክታት ክህልዎ ኣለዎ፦ ፊደላት፣ ቁጽሪታት፣ ነጥቢ፣ ሰረዝ ወይ ትሕተ-መስመር።',
  'Os perfis SUP e PRO precisam de pelo menos uma rota.': 'ፕሮፋይላት SUP ን PRO ን እንተወሓደ ሓደ መስመር የድልዮም።',
  'Outras rotas, separadas por vírgulas': 'ካልኦት መስመራት፣ ብኮማ ዝተፈላለዩ',
