    'ምዝገባ ዓማዊል ካብ ማዕከን rtm-clientes ይመጽእ (ካብ ምምሕዳራዊ ክፍሊ RTM ዝወጸ ፋይል «ዓማዊል»)። ኣብ ሰርቨር፡ ነዚ ማዕከን ኣብ ጎኒ ማህደር መርበብ-ገጽ ቅድሑ፡ ወይ ነቲ ፋይል ኣብ RTM_CLIENTES_JSON ኣብ .env ኣመልክቱ።',
