  'Artigo (código, descrição e marca)': 'ኣቕሓ (ኮድ፡ መግለጺን ምልክት ንግድን)',
  'Quantidade e preço unitário': 'ብዝሕን ዋጋ ንሓደን',
  'Valor sem IVA, IVA e valor com IVA': "ዋጋ ብዘይ ግ.ወ.ዋ፡ ግ.ወ.ዋ ከምኡ'ውን ዋጋ ምስ ግ.ወ.ዋ",
