  Quantidade: 'ብዝሒ',
  'Valor sem IVA e com IVA': 'ዋጋ ብዘይ ግ.ወ.ዋን ምስ ግ.ወ.ዋን',
  'Meio de cobrança (dinheiro, Multicaixa, transferência)': 'ኣገባብ ክፍሊት (ጥረ ገንዘብ፡ Multicaixa፡ ምስግጋር ገንዘብ)',
  'Valor recebido': 'ዝተኣከበ መጠን ገንዘብ',
  Ativo: 'ንጡፍ',
  Activo: 'ንጡፍ',
  Inactivo: 'ዘይንጡፍ',
  Erro: 'ጌጋ',
  'Taxa de cobrança: {p}': 'መጠን ምእካብ ገንዘብ፦ {p}',
  '{n} documentos, {l} linhas, {v} facturados, de {a} a {b}. O ficheiro é emitido uma única vez: guarde-o e carregue-o no SAP; estes documentos não poderão entrar noutro ficheiro.':
    '{n} ሰነዳት፣ {l} ረድፍታት፣ {v} ዝተፋክቱሩ፣ ካብ {a} ክሳብ {b}። እቲ ፋይል ሓንሳእ ጥራይ እዩ ዝወጽእ፦ ኣቐምጥዎ እሞ ናብ SAP ስቐልዎ፤ እዞም ሰነዳት ኣብ ካልእ ፋይል ክኣትዉ ኣይክእሉን።',
  'excluídos: só podem ser emitidos uma vez': 'ተገሊሎም፦ ሓንሳእ ጥራይ እዮም ክወጹ ዝኽእሉ',
  'Registo de ficheiros emitidos': 'መዝገብ ዝወጹ ፋይላት',
  'Cada ficheiro é emitido uma única vez, com número sequencial e impressão digital SHA-256. Depois de carregar no SAP, confirme o carregamento. Um lote ainda não carregado só pode ser anulado, com motivo, por outra pessoa que não quem o emitiu; a anulação liberta os documentos para um novo ficheiro.':
    'ነፍሲ ወከፍ ፋይል ሓንሳእ ጥራይ እዩ ዝወጽእ፣ ምስ ተኸታታሊ ቁጽሪን ኣሻራ SHA-256ን። ናብ SAP ምስ ሰቐልኩም፣ ምስቃሉ ኣረጋግጹ። ገና ዘይተሰቕለ ሎት ክፈርስ ዝኽእል፣ ምስ ምኽንያት፣ ብኻልእ ሰብ ጥራይ እዩ (ብዘውጽኦ ሰብ ኣይኮነን)፤ ምፍራስ ነቶም ሰነዳት ንሓድሽ ፋይል ሓራ ይገብሮም።',
  'por {p} em {d}': 'ብ{p} ኣብ {d}',
  'Emitido em': 'ዝወጸሉ ዕለት',
  Acções: 'ተግባራት',
