  'Stock final nas centrais': 'ናይ መወዳእታ ስቶክ ኣብ ማእከላይ መኻዝን',
  'Sem armazéns ou produtos correspondentes aos filtros aplicados.': 'ምስቶም ዝተተግበሩ መጻረዪታት ዝሰማማዕ መኽዘን ወይ ኣቕሓ የለን።',
