  'perfis {p}': 'ፕሮፋይላት {p}',
  Perfis: 'ፕሮፋይላት',
  'Os perfis do sistema são fixos. Um perfil novo começa com as permissões do perfil de origem e passa a ser uma coluna da matriz, onde as pode ajustar.':
    'ፕሮፋይላት ስርዓት ዘይቕየሩ እዮም። ሓድሽ ፕሮፋይል ብፍቓዳት ናይቲ መበገሲ ፕሮፋይል ይጅምር፣ ኣብ ሰንጠረዥ ፍቓዳት ድማ ዓምዲ ይኸውን፣ ኣብኡ ፍቓዳቱ ከተስተኻኽልዎ ትኽእሉ።',
  'Perfis de acesso e respectivas características.': 'ፕሮፋይላት ፍቓድን ባህርያቶምን።',
  Sistema: 'ስርዓት',
