  'Só as suas rotas': 'ናይ ገዛእ መስመራት ጥራይ',
  Obrigatória: 'ግዴታ',
  'Copiado de': 'ዝተቐድሐሉ',
  Âmbito: 'ወሰን',
  Contas: 'ኣካውንታት',
  'Novo perfil': 'ሓድሽ ፕሮፋይል',
  'O perfil novo copia as permissões do perfil de origem; depois ajuste-as na matriz de acessos.':
    'እቲ ሓድሽ ፕሮፋይል ፍቓዳት ናይቲ መበገሲ ፕሮፋይል ይቐድሕ፤ ድሕሪኡ ኣብ ሰንጠረዥ ፍቓዳት ኣስተኻኽልዎም።',
  '{n} contas com este perfil.': '{n} ኣካውንታት ምስዚ ፕሮፋይል።',
  'ex.: VENDAS2': 'ኣብነት፦ PRO2',
  'ex.: Vendedor de loja': 'ኣብነት፦ ሸያጢ ድኳን',
  'Nenhum (sem permissões)': 'ሓደ እኳ የለን (ፍቓድ የብሉን)',
  'Copiar as permissões de': 'ፍቓዳት ቅዳሕ ካብ',
  'Vê só as rotas atribuídas a cada conta (como supervisores e promotores)': 'ነፍሲ ወከፍ ኣካውንት ዝተመደበሉ መስመራት ጥራይ ይርኢ (ከም ተቖጻጸርትን ወከልቲ መሸጣን)',
  'Verificação em dois passos obrigatória': 'ምርግጋጽ ብኽልተ ስጉምቲ ግዴታ',
  'Perfil activo': 'ፕሮፋይል ንጡፍ',
  'Apagar perfil': 'ፕሮፋይል ሰርዝ',
  'O perfil {c} e as suas permissões na matriz são apagados.': 'ፕሮፋይል {c} ምስ ፍቓዳቱ ኣብ ሰንጠረዥ ይስረዝ።',
  Apagar: 'ሰርዝ',
  'Perfil apagado.': 'ፕሮፋይል ተሰሪዙ።',
  'Criar perfil': 'ፕሮፋይል ፍጠር',
  'Perfil {c} criado. Ajuste as permissões na matriz de acessos.': 'ፕሮፋይል {c} ተፈጢሩ። ኣብ ሰንጠረዥ ፍቓዳት ፍቓዳቱ ኣስተኻኽሉ።',
  'Perfil guardado.': 'ፕሮፋይል ተቐሚጡ።',
  'Perfil criado': 'ፕሮፋይል ተፈጢሩ',
  'Perfil apagado': 'ፕሮፋይል ተሰሪዙ',
  Ontem: 'ትማሊ',
  'Informação actual · actualizada às {h} · actualiza sozinha a cada 5 min': 'ህሉው ሓበሬታ · ኣብ {h} ተሓዲሱ · ኣብ ነፍሲ ወከፍ 5 ደቒቕ ባዕሉ ይሕደስ',
  'Período fechado · dados lidos às {h}': 'ዝተዓጽወ እዋን · ሓበሬታ ኣብ {h} ተነቢቡ',
  Actualizar: 'ኣሐድስ',
  'Sem registos para mostrar.': 'ዝርአ መዝገብ የለን።',
  'Activar a gestão de contas no portal': 'ኣብ ፖርታል ምምሕዳር ኣካውንታት ኣግብር',
  'As contas vêm ainda da lista antiga e não podem ser criadas nem alteradas aqui. Ao activar, cada conta passa para a lista nova com correio electrónico obrigatório, perfil e rotas, e a sua conta fica super administrador. As palavras-passe actuais mantêm-se. Faz-se uma só vez.':
    'ኣካውንታት ገና ካብቲ ኣረጊት ዝርዝር እዮም ዝመጹ፣ ኣብዚ ክፍጠሩ ወይ ክቕየሩ ኣይክእሉን። ምስ ኣግበርኩም፣ ነፍሲ ወከፍ ኣካውንት ምስ ግዴታዊ ኢመይል፣ ፕሮፋይልን መስመራትን ናብቲ ሓድሽ ዝርዝር ይሰጋገር፣ ናትኩም ኣካውንት ድማ ሱፐር ኣመሓዳሪ ይኸውን። ህሉዋት መሕለፊ ቃላት ይቕጽሉ። እዚ ሓንሳእ ጥራይ እዩ ዝግበር።',
  'As contas vêm ainda da lista antiga e não podem ser criadas nem alteradas aqui. Peça ao administrador da plataforma (conta admin) para activar a gestão de contas.':
    'ኣካውንታት ገና ካብቲ ኣረጊት ዝርዝር እዮም ዝመጹ፣ ኣብዚ ክፍጠሩ ወይ ክቕየሩ ኣይክእሉን። ኣመሓዳሪ ናይቲ መድረኽ (ኣካውንት admin) ምምሕዳር ኣካውንታት ከግብር ሕተትዎ።',
  'Activar a gestão': 'ምምሕዳር ኣግብር',
  'Activar a gestão de contas': 'ምምሕዳር ኣካውንታት ኣግብር',
  'Reveja cada conta. O correio electrónico é obrigatório para as contas activas (serve para recuperar a palavra-passe e para os avisos). Contas que já não são usadas: desactive-as.':
    'ነፍሲ ወከፍ ኣካውንት ደጊምኩም ርኣዩ። ንንጡፋት ኣካውንታት ኢመይል ግዴታ እዩ (ንምምላስ መሕለፊ ቃልን ንመጠንቀቕታታትን የገልግል)። ዘይጥቀሙሎም ኣካውንታት፦ ኣሰንክልዎም።',
  'ex.: 1001, 1002': 'ኣብነት፦ 1001፣ 1002',
  'a sua conta': 'ናትኩም ኣካውንት',
  Conta: 'ኣካውንት',
  'A sua conta fica super administrador. Indique as duas pessoas da Administração que aprovaram (controlo dual).':
    'ናትኩም ኣካውንት ሱፐር ኣመሓዳሪ ይኸውን። እቶም ዘጽደቑ ክልተ ኣባላት ምምሕዳር ኣመልክቱ (ድርብ ቁጽጽር)።',
  'Gestão de contas activada: {n} contas na lista nova. Active já a verificação em dois passos da sua conta.':
    'ምምሕዳር ኣካውንታት ተግቢሩ፦ {n} ኣካውንታት ኣብቲ ሓድሽ ዝርዝር። ሕጂ ንኣካውንትኩም ምርግጋጽ ብኽልተ ስጉምቲ ኣግብሩ።',
  'Gestão de contas activada': 'ምምሕዳር ኣካውንታት ተግቢሩ',
  'A sincronização precisa do servidor da plataforma (PHP) e da base de dados do Pinguim BO.': 'ምትእስሳር ሰርቨር ናይቲ መድረኽን ዳታቤዝ Pinguim BOን የድልዮ።',
  'há {h} h {m} min': 'ቅድሚ {h} ሰዓት {m} ደቒቕ',
  'há {n} dias': 'ቅድሚ {n} መዓልታት',
  'Ligação à base de dados do Pinguim BO (SQL Server) no .env do servidor': 'ርክብ ምስ ዳታቤዝ Pinguim BO (SQL Server) ኣብ .env ናይ ሰርቨር',
  'Tabela SYNC_PHSE_HISTORY (fim de cada sincronização por loja/rota)': 'ሰንጠረዥ SYNC_PHSE_HISTORY (መወዳእታ ነፍሲ ወከፍ ምትእስሳር ብድኳን/መስመር)',
  'Em dia': 'ብግዜኡ',
  'última sincronização há menos de {h} h': 'ናይ መወዳእታ ምትእስሳር ቅድሚ ትሕቲ {h} ሰዓት',
  Atenção: 'ኣቓልቦ',
  'entre {a} e {b} h': 'ኣብ መንጎ {a}ን {b}ን ሰዓት',
  Crítico: 'ከቢድ',
  'mais de {h} h ou sem registo': 'ልዕሊ {h} ሰዓት ወይ መዝገብ የለን',
  'Sem registo': 'መዝገብ የለን',
  'Última sincronização da rede': 'ናይ መወዳእታ ምትእስሳር ኣብ መርበብ',
  'Estado pelo tempo desde a última sincronização terminada de cada telemóvel (hora do servidor: {h}). Actualiza sozinho a cada minuto.':
    'ኩነታት ብግዜ ካብ ናይ መወዳእታ ዝተዛዘመ ምትእስሳር ነፍሲ ወከፍ ስማርትፎን (ሰዓት ሰርቨር፦ {h})። ኣብ ነፍሲ ወከፍ ደቒቕ ባዕሉ ይሕደስ።',
  'Estado por telemóvel': 'ኩነታት ብስማርትፎን',
  'Do mais grave para o mais recente. Sem registo: rota do portal sem nenhuma sincronização na base de dados.':
    'ካብቲ ዝኸበደ ናብቲ ዝሓደሰ። መዝገብ የለን፦ ኣብ ዳታቤዝ ዋላ ሓደ ምትእስሳር ዘይብሉ መስመር ፖርታል።',
