  'Exportar tudo': 'ኩሉ ኣውጽእ',
  'Um só Excel com os indicadores, os relatórios de todas as páginas e os dados de base do período': 'ሓደ Excel ምስ መመልከቲታት፣ ጸብጻባት ኩሎም ገጻትን መሰረታዊ ሓበሬታ ናይቲ እዋንን',
