  'Sem histórico suficiente: rotas {r}.': 'እኹል ታሪኽ የለን፦ መስመራት {r}።',
  'Método: média ponderada do mesmo dia da semana nas últimas 6 semanas (a mais recente pesa mais), multiplicada pela tendência. A precisão é medida todos os dias e mostrada sempre. As quantidades sugeridas no plano de cargas usam a tendência de cada rota.':
    'ኣገባብ፦ ዝተመዘነ ማእከላይ ተመሳሳሊ መዓልቲ ሰሙን ኣብ ዝሓለፉ 6 ሰሙናት (እቲ ሓድሽ ዝያዳ ይኸብድ)፡ ብኣንፈት ተባዚሑ። ልክዕነት ኩሉ መዓልቲ ይዕቀንን ኩሉ ግዜ ይርአን። ኣብ መደብ ጽዕነት ዝቐረባ ብዝሒታት ኣንፈት ነፍሲ ወከፍ መስመር ይጥቀማ።',
  'Previsão por rota (Kz)': 'ትንበያ ብመስመር (Kz)',
  'Passe o rato por cima de um valor para ver o intervalo de 80%.': '80% ክሊ ንምርኣይ ኣብ ልዕሊ ዋጋ ኣመልክት።',
  'O assistente ainda não está configurado no servidor: correr «php ferramentas/configurar-ia.php» com a chave da API da conta comercial da empresa.':
    'ሓጋዚ ገና ኣብ ሰርቨር ኣይተዳለወን፦ «php ferramentas/configurar-ia.php» ብመፍትሕ ናይ ንግዳዊ ሕሳብ ትካል ኣካይድ።',
  'Pergunte sobre as vendas, as rotas, os clientes, os alertas e a previsão': 'ብዛዕባ መሸጣታት፡ መስመራት፡ ዓማዊል፡ መጠንቀቕታታትን ትንበያን ሕተት',
