  'Nova conversa': 'ሓድሽ ዝርርብ',
  'Cada ecrã (TV ou mini-PC ligado à TV) usa uma ligação própria, sem conta nem palavra-passe, que só mostra o painel: vendas do dia, classificação e destaques, sem clientes nem NIF. Pode revogá-la a qualquer momento.':
    'ነፍሲ ወከፍ ስክሪን (ቴሌቪዥን ወይ ምስኡ ዝተኣሳሰረ ንኡስ ኮምፒተር) ናቱ ሊንክ ይጥቀም፡ ብዘይ ሕሳብን ቃለ ምሕላፍን፡ ሰሌዳ ጥራይ ዘርኢ፦ መሸጣታት ሎሚ፡ ደረጃን ፍሉያትን፡ ብዘይ ዓማዊልን ቁጽሪ ግብርን። ኣብ ዝኾነ እዋን ክትስርዞ ትኽእል።',
  'Ainda não há ligações activas.': 'ገና ንጡፋት ሊንክታት የለዉን።',
