    'ነፍሲ ወከፍ መኪና ክትጸውሮ እትኽእል ዝለዓለ ክብደት (kg)። እቲ መደብ ካብቲ ገና ዝሰፍሕ ንላዕሊ ክጽዓን ኣይፈቅድን።',
  'Capacidade (kg)': 'ዓቕሚ (kg)',
  'Atingido o peso máximo da viatura {m}: só cabem mais {q} de {a}.': 'ዝለዓለ ክብደት መኪና {m} በጺሑ፦ ካብ {a} ተወሳኺ {q} ጥራይ ይሰፍሕ።',
  'Stock negativo na carrinha': 'ኣብ መኪና ኣሉታዊ ክምችት',
  'Vendido mais do que estava na carrinha': 'ካብቲ ኣብ መኪና ዝነበረ ንላዕሊ ተሸጢ',
  'Movimento sem documento': 'ሰነድ ዘይብሉ ምንቅስቓስ',
