  'Total do IVA': 'ጠቕላላ ግብሪ ወሰኽ ዋጋ',
  Amanhã: 'ጽባሕ',
  'compra a cada {n} dias': 'ኣብ ነፍሲ ወከፍ {n} መዓልቲ ይዕድግ',
  'última compra {d} (há {n} dias)': 'ናይ መወዳእታ ዕድጊ {d} (ቅድሚ {n} መዓልቲ)',
