  'Já compra o habitual da rota.': 'ልሙድ ናይ መስመር ድሮ ይዕድግ እዩ።',
  'A carteira é calculada todas as noites, entre as 04:00 e as 07:00. Ainda não há cálculo.': 'ዝርዝር ዓማዊል ኩሉ ለይቲ ኣብ መንጎ 04:00ን 07:00ን ይሕሰብ። ገና ዝተሓሰበ የለን።',
  'Clientes a visitar': 'ዝብጻሕ ዓማዊል',
  Parados: 'ዝደው በሉ',
  'mais de 2 vezes o seu intervalo habitual': 'ካብ ልሙድ ግዜኦም ልዕሊ ክልተ ዕጽፊ',
