  'compra em atraso face ao seu ritmo': 'ብመሰረት ልሙዶም ዝደንጎየ ዕድጊ',
  'dia habitual de compra': 'ልሙድ መዓልቲ ዕድጊ',
  'Nenhum cliente previsto para este dia.': 'ነዛ መዓልቲ ዝተተለመ ዓሚል የለን።',
  'Os parados primeiro e, dentro de cada estado, os de maior valor por compra. Encomenda sugerida pela quantidade habitual de cada cliente.':
    'ዝደው በሉ ቀዳሞት፡ ኣብ ነፍሲ ወከፍ ኩነታት ድማ ዝለዓለ ዋጋ ዕድጊ ዘለዎም። ዝተመኽረ ትእዛዝ ብልሙድ ብዝሒ ነፍሲ ወከፍ ዓሚል።',
  'Calculado em {d} a partir das vendas do Pinguim BO dos últimos 120 dias.': 'ብ{d} ካብ መሸጣታት Pinguim BO ናይ ዝሓለፉ 120 መዓልቲ ዝተሓሰበ።',
  'Anomalias de vendas': 'ዘይልሙዳት መሸጣታት',
