  'uma tarefa por problema': 'ሓደ ዕማም ንነፍሲ ወከፍ ጸገም',
  'Auditoria contínua: verificar cada caso no Pinguim BO. Uma anomalia não é uma falha: é um caso fora do padrão que merece ser confirmado.':
    'ቀጻሊ ኦዲት፦ ነፍሲ ወከፍ ጉዳይ ኣብ Pinguim BO ኣረጋግጽ። ዘይልሙድ ጉድለት ኣይኮነን፦ ክረጋገጽ ዝግበኦ ፍሉይ ጉዳይ እዩ።',
  'Qualidade dos dados': 'ብቕዓት ሓበሬታ',
  'Corrigir na origem (Pinguim BO). A lista é refeita todas as noites: o que for corrigido sai sozinho.':
    'ኣብ መበቈል (Pinguim BO) ኣረም። እቲ ዝርዝር ኩሉ ለይቲ ይሕደስ፦ ዝተኣረመ ባዕሉ ይወጽእ።',
  'Calculado em {d}.': 'ብ{d} ዝተሓሰበ።',
