  'Diferenças por aprovar': 'ዝጽደቑ ፍልልያት',
  'Primeiro as que pedem atenção. As carrinhas cuja contagem bate certo em todos os artigos fecham sozinhas.':
    'ኣቓልቦ ዝሓትታ ቀዳመን። ቆጸራኤን ኣብ ኩሉ ኣቕሓ ዝሰማማዕ መካይን ብገዛእ ርእሰን ይዕጸዋ።',
  'Sem movimentos nas carrinhas neste dia.': 'ኣብዚ መዓልቲ ናይ መካይን ምንቅስቓስ የለን።',
  'Origem dos dados': 'ምንጪ ሓበሬታ',
  'Cada bloco passa a ter dados quando a ligação ao sistema de origem existir. O portal só lê.':
    'ነፍሲ ወከፍ ክፋል ምስ ምንጪ ስርዓት ምርኻብ ምስ ዝህሉ ሓበሬታ የርኢ። እቲ ፖርታል ዘንብብ ጥራይ እዩ።',
  'Acessos (utilizadores, perfis e matriz), histórico de auditoria, actualizações, módulos e ensaio. Não se desliga.':
    'መእተዊ (ተጠቀምቲ፡ መገለጺታትን ሰሌዳን)፡ ታሪኽ ምርመራ፡ ምሕዳስ፡ ሞጁላትን ፈተነን። ኣይጠፍእን።',
  'Estado da comunicação dos documentos à AGT, lido do Pinguim BO.': 'ኩነታት ምልኣኽ ሰነዳት ናብ AGT፡ ካብ Pinguim BO ዝተነበ።',
  'Carteira de clientes, cadastros e análise de cadastros.': 'ዝርዝር ዓማዊል፡ ምዝገባታትን ትንተና ምዝገባታትን።',
  'Cobranças por meio de pagamento e facturas pendentes.': 'ኣኼባ ገንዘብ ብመንገዲ ክፍሊትን ዘይተኸፍላ ፋክቱራታትን።',
  'Smartphones e impressoras do terreno, sincronização e documentos dos equipamentos.': 'ናይ ሜዳ ስማርት ስልክታትን መሕተምታትን፡ ምስምማዕን ሰነዳት መሳርሒታትን።',
  'Previsão de vendas, assistente de IA, painel da sala comercial, gráficos de gestão, resumo diário, fecho do dia e app de gestão.':
    'ትንበያ መሸጣ፡ ሓጋዚ ሰብ ሰርሖ ኣእምሮ፡ መርኣዪ ክፍሊ ንግዲ፡ ሰንጠረዣት ምሕደራ፡ መዓልታዊ ጽማቝ፡ መዕጸዊ መዓልትን ኣፕ ምሕደራን።',
  'Logística e carrinhas': 'ሎጂስቲክስን መካይንን',
  'Plano de cargas, conciliação e painel da carrinha (fecho de rota), registo de cargas e stock por carrinha e armazém.':
    'መደብ ጽዕነት፡ ምስምማዕን መርኣዪ መኪናን (መዕጸዊ መስመር)፡ መዝገብ ጽዕነትን ክምችት ብመኪናን መኽዘንን።',
  'Núcleo da plataforma': 'ማእከል መድረኽ',
  'Pedidos feitos pelos clientes com o cartaz QR da loja.': 'ብናይ ድኳን QR መለጠፊ ብዓማዊል ዝቐረቡ ትእዛዛት።',
  'Integração SAP': 'ምትእስሳር SAP',
  'Ficheiro de vendas para o SAP (estrutura do modelo original, sem alterações) e lotes emitidos.': 'ፋይል መሸጣ ን SAP (ቅርጺ ናይ መበገሲ ሞዴል፡ ብዘይ ለውጢ) ን ዝወጹ ጉጅለታትን።',
  'Visitas do dia, plano de visitas, percurso do dia, optimização de rotas, prospecção, zonas e distribuidores.':
    'ናይ መዓልቲ ምብጻሓት፡ መደብ ምብጻሓት፡ ናይ መዓልቲ ጉዕዞ፡ ምምሕያሽ መስመራት፡ ምድላይ ዓማዊል፡ ዞባታትን ኣከፋፈልትን።',
  'Vendas por promotor, dia, cliente, artigo e marca, classificação e documentos.': 'መሸጣ ብኣስፋሕፋሒ፡ መዓልቲ፡ ዓሚል፡ ኣቕሓን ዓይነትን፡ ደረጃን ሰነዳትን።',
  Piloto: 'ፈተነ ምጅማር',
  Desligado: 'ጠፊኡ',
  'Para todos os perfis, conforme a matriz de acessos.': 'ንኹሎም መገለጺታት፡ ከም ሰሌዳ መእተዊ።',
  'Só para o super administrador e o administrador da plataforma.': 'ንልዑል ኣመሓዳሪን ኣመሓዳሪ መድረኽን ጥራይ።',
  'Para ninguém: as páginas saem do menu e a API recusa os pedidos.': 'ንሓደ እኳ፡ ገጻት ካብ ዝርዝር ይወጹ፡ መተሓሓዚ ድማ ሕቶታት ይነጽግ።',
