  'Confirmar a revisão de acessos {t}': 'ምርመራ መእተዊታት {t} ኣረጋግጽ',
  'Confirme que reviu quem tem acesso a quê. O que retirar, faça-o em Acessos.': 'መን ናብ እንታይ መእተዊ ከም ዘለዎ ከም ዝመርመርካ ኣረጋግጽ። ዝእለ መእተዊ ኣብ መእተዊታት ኣልግሶ።',
