  'Valor do portal': 'ዋጋ ፖርታል',
  'Valor do portal (V: ver o cálculo; G: alterar os parâmetros)': 'ዋጋ ፖርታል (V፦ ስሌት ምርኣይ፤ G፦ መለክዒታት ምቕያር)',
  'Previsão de vendas, assistente de IA, painel da sala comercial, gráficos de gestão, resumo diário, fecho do dia, app de gestão e valor do portal para a Naval.':
    'ትንበያ መሸጣ፡ ሓጋዚ ሰብ ሰራሕ ኣእምሮ፡ ሰሌዳ ክፍሊ ንግዲ፡ ሰንጠረዛት ምሕደራ፡ ዕለታዊ ጽማቝ፡ መዕጸዊ መዓልቲ፡ መተግበሪ ምሕደራን ዋጋ ፖርታል ንናቫልን።',
  'Custo de uma hora de trabalho (Kz)': 'ዋጋ ሓንቲ ሰዓት ስራሕ (Kz)',
  'Minutos poupados por rota fechada automaticamente': 'ዝተቖጠባ ደቓይቕ ንነፍሲ ወከፍ ብባዕሉ ዝተዓጽወ መስመር',
  'Minutos poupados por rota conciliada no portal (em vez de papel ou Excel)': 'ዝተቖጠባ ደቓይቕ ንነፍሲ ወከፍ ኣብ ፖርታል ዝተሰማምዐ መስመር (ኣብ ክንዲ ወረቐት ወይ Excel)',
  'Minutos poupados por ficheiro SAP gerado': 'ዝተቖጠባ ደቓይቕ ንነፍሲ ወከፍ ዝተፈጥረ ፋይል SAP',
  'Minutos poupados por relatório exportado': 'ዝተቖጠባ ደቓይቕ ንነፍሲ ወከፍ ዝወጸ ጸብጻብ',
  'Perda média de stock por rota e por mês antes do portal (Kz)': 'ማእከላይ ክሳራ ክምችት ንነፍሲ ወከፍ መስመርን ወርሕን ቅድሚ ፖርታል (Kz)',
  'Licença de uma solução comercial equivalente, por utilizador e por mês (Kz)': 'ፍቓድ ማዕረ ንግዳዊ ፍታሕ፡ ንነፍሲ ወከፍ ተጠቃሚን ወርሕን (Kz)',
  'Custo de fazer o portal de novo com uma empresa de software (Kz)': 'ዋጋ ፖርታል ብትካል ሶፍትዌር ብሓድሽ ምስራሕ (Kz)',
  'Anos de amortização do custo de reconstrução': 'ዓመታት ምምላስ ዋጋ ዳግመ ምህናጽ',
  'Câmbio: Kz por 1 euro (para mostrar também em euros)': 'ምንዛሪ፦ Kz ንሓደ ዩሮ (ብዩሮ እውን ንምርኣይ)',
  'Tempo = (fechos automáticos × minutos + rotas conciliadas × minutos + ficheiros SAP × minutos + relatórios × minutos) ÷ 60 × custo da hora.':
    'ግዜ = (ብባዕሉ ዝተዓጽዉ × ደቓይቕ + ዝተሰማምዑ መስመራት × ደቓይቕ + ፋይላት SAP × ደቓይቕ + ጸብጻባት × ደቓይቕ) ÷ 60 × ዋጋ ሰዓት።',
  'Stock = perda de referência por rota × rotas activas − faltas aprovadas (nunca abaixo de zero).':
    'ክምችት = መወከሲ ክሳራ ንመስመር × ንጡፋት መስመራት − ዝጸደቑ ጉድለታት (ካብ ዜሮ ፈጺሙ ኣይንኣስን)።',
  'Licenças = utilizadores que entraram no mês × licença de uma solução comercial equivalente.': 'ፍቓዳት = ኣብቲ ወርሒ ዝኣተዉ ተጠቀምቲ × ፍቓድ ማዕረ ንግዳዊ ፍታሕ።',
  'Construção = custo de fazer o portal de novo ÷ (anos de amortização × 12).': 'ምህናጽ = ዋጋ ፖርታል ብሓድሽ ምስራሕ ÷ (ዓመታት ምምላስ × 12)።',
  'Os documentos anulados mostram o valor que o portal deixou fora das vendas e do SAP: é valor corrigido, não poupança, e não entra no total.':
    'ዝተሰረዙ ሰነዳት ፖርታል ካብ መሸጣን SAPን ዘውጽኦ ዋጋ የርእዩ፦ ምእራም እዩ እምበር ቁጠባ ኣይኮነን፡ ኣብ ድምር ድማ ኣይኣቱን።',
  'Só a Direcção altera os parâmetros do cálculo.': 'መለክዒታት ስሌት ዝቕይር ኣመራርሓ ጥራይ እዩ።',
  'Valor inválido num dos parâmetros.': 'ኣብ ሓደ ካብ መለክዒታት ዘይቅቡል ዋጋ።',
  'A amortização tem de ser de pelo menos 1 ano.': 'ምምላስ እንተወሓደ 1 ዓመት ክኸውን ኣለዎ።',
  'Módulo «{m}» ligado': 'ሞጁል «{m}» ተወሊዑ',
  'O núcleo nunca se desliga.': 'እቲ ማእከል ፈጺሙ ኣይጠፍእን።',
  'Ligar para todos': 'ንኹሉ ኣወልዕ',
  'Pôr em piloto': 'ናብ ፈተነ ኣሕልፍ',
  'Desligar o módulo': 'እቲ ሞጁል ኣጥፍእ',
  'Ligar o módulo para todos': 'እቲ ሞጁል ንኹሉ ኣወልዕ',
  'Tentativa {n} de 3: o servidor volta a tentar sozinho dentro de 5 minutos.': 'ፈተነ {n} ካብ 3፦ እቲ ሰርቨር ኣብ ውሽጢ 5 ደቓይቕ ባዕሉ ደጊሙ ክፍትን እዩ።',
  'As 3 tentativas falharam. Corrija a causa (por exemplo, uma pasta do ensaio em uso) e carregue em «Repetir no ensaio».':
    '3 ፈተነታት ፈሺሎም። ነቲ ጠንቂ ኣዕርዩ (ንኣብነት፡ ኣብ ስራሕ ዘሎ ማህደር ፈተነ) ድሕሪኡ «ኣብ ፈተነ ድገሞ» ጠውቑ።',
  'Repetir no ensaio': 'ኣብ ፈተነ ድገሞ',
  'A versão volta a instalar-se no ensaio nos próximos 5 minutos.': 'እቲ ሕታም ኣብ ዝመጽእ 5 ደቓይቕ ደጊሙ ኣብ ፈተነ ክጸዓን እዩ።',
  'A instalação no ensaio falhou: não pode ser aprovada ainda': 'ምጽዓን ኣብ ፈተነ ፈሺሉ፦ ገና ክጸድቕ ኣይክእልን',
  'Não há nenhuma instalação falhada no ensaio para repetir.': 'ክድገም ዝኽእል ዝፈሸለ ምጽዓን ኣብ ፈተነ የለን።',
  Vigilância: 'ምክትታል',
  'última verificação: {d}': 'ናይ መወዳእታ ምርመራ፦ {d}',
  'ainda sem verificações': 'ገና ምርመራ የለን',
  'Problemas abertos': 'ክፉታት ጸገማት',
  'Verificações de negócio': 'ምርመራታት ንግዲ',
  'Atenção da vigilância': 'መጠንቀቕታ ምክትታል',
  'Problemas detectados em produção': 'ኣብ ስራሕ ዝተረኽቡ ጸገማት',
  'Agrupados por assinatura e sem dados pessoais. Os que estão no GitHub são corrigidos de madrugada, com teste, e seguem pelo ensaio.':
    'ብፊርማ ዝተጠርነፉን ብዘይ ውልቃዊ ሓበሬታን። እቶም ኣብ GitHub ዘለዉ ብለይቲ ብፈተነ ይእረሙ፣ ብመንገዲ ፈተነ ድማ ይሓልፉ።',
  Problema: 'ጸገም',
  Última: 'ናይ መወዳእታ',
  GitHub: 'GitHub',
  'A GitHub App do portal não tem permissão para criar «issues» (dar «Issues: Read and write» à App no GitHub).':
    'እቲ ናይ ፖርታል መተግበሪ GitHub ጸገማት ክፈጥር ፍቓድ የብሉን (ኣብ GitHub ናይ ምንባብን ምጽሓፍን ፍቓድ ጸገማት ሃቦ)።',
  'Armazém confirmado': 'መኽዘን ተረጋጊጹ',
  'Armazém por confirmar': 'መኽዘን ገና ኣይተረጋገጸን',
  confirmado: 'ተረጋጊጹ',
  'pelo código': 'ብኮድ',
  'pelo nome': 'ብስም',
  'Só este é a carrinha': 'እዚ ጥራይ እዩ ናይ ቫን',
  'Armazém da carrinha {r} confirmado.': 'መኽዘን ቫን {r} ተረጋጊጹ።',
