    'ዋጋ ብዘይ ግ.ወ.ዋ ናይ ነፍሲ ወከፍ ወኪል መሸጣ ኣብቶም {n} ኣብ ትካል ብዝያዳ ዝሽየጡ ኣቕሑ፤ ዝያዳ ዝጸልመተ፣ ዝያዳ ዝዓበየ ዋጋ። ግደ ናይቲ ወኪል መሸጣ ንምርኣይ ኣብ ክፍሊ ጠቋሚ ኣቐምጡ።',
