    'ኣቕሑ A፦ እቶም 80% ዋጋ ናይቲ ወኪል መሸጣ ዝገብሩ (ትንተና ABC)። ዓማዊል፦ እቶም ኣብቲ እዋን ካብቲ ወኪል መሸጣ ዝዓደጉ (ቍጽራዊ ምዝርጋሕ)።',
