    'ኩሉ ብመኪና ዝተመልሰ (ዘይተሸጡ ኣቕሑን ተመላሲን) ቍጸሩን ብዝተገልጸ ኣሃዱ ብዝሒ ጸሓፉን፤ ዋላ ሓደ እንተዘይተመልሰ 0። እዚ ወረቐት ብዝሒ ስርዓት ኣየርእን። ኣይትደምስሱ፦ እንተተጋገኹም፣ ሰርዙ፣ ኣብ ጎኑ ጸሓፉን ፈርሙን።',
