    "ጸብጻብ መሸጣ ማርኬቲንግ (ጽማቕ፣ ኣከፋፍላታት ብወኪል መሸጣ፣ ካዝና፣ መዝገብ መሸጣን ንብረት መካይንን)፣ ኩሎም ምንጭታት ናይታ መዓልቲ ምሉኣት ክኾኑ ከለዉ ጥራይ ዝዳሎ፣ ከምኡ'ውን ወረቐት ካዝና ግምጃ ቤት።",
