  'Necessário por dia': 'ኣብ መዓልቲ ዘድሊ',
  Projecção: 'ግምት',
  'Pelo mínimo crescente: ritmo do mês anterior + crescimento mínimo': 'ብዝውስኽ ዝተሓተ ደረጃ፦ ቅልጣፈ ዝሓለፈ ወርሒ + ዝተሓተ ዕቤት',
  'Pela tendência das vendas + crescimento': 'ብኣንፈት መሸጣ + ዕቤት',
  'Calculados sozinhos no início de cada mês a partir das vendas diárias: previsão do mês (mesmo dia da semana × tendência) + {a}% de crescimento, e nunca abaixo do ritmo por dia útil do mês anterior (realizado ou objectivo, o maior) + {m}%. Repartidos pelos dias úteis e congelados durante o mês.':
    'ኣብ መጀመርታ ነፍሲ ወከፍ ወርሒ ካብ ዕለታዊ መሸጣ ባዕሉ ዝሕሰብ፦ ግምት ወርሒ (ተመሳሳሊ መዓልቲ ሰሙን × ኣንፈት) + {a}% ዕቤት፣ ካብ ቅልጣፈ ኣብ መዓልቲ ስራሕ ናይ ዝሓለፈ ወርሒ (ዝተረኽበ ወይ ዕላማ፣ እቲ ዝዓበየ) + {m}% ፈጺሙ ዘይውሕድ። ኣብ መዓልታት ስራሕ ዝተመቓቐለን ኣብ ውሽጢ ወርሒ ዘይቅየርን።',
