  'Código do lacre': 'ኮድ ማሕተም',
  Requisitante: 'ሓታቲ',
  Aprovador: 'ኣጽዳቒ',
  'ao gravar': 'ምስ ምዕቃብ',
  'Retirar aprovação': 'ምጽዳቕ ኣልዕል',
